import express from 'express';
import cors from 'cors';

const app = express();

app.use(cors());
app.use(express.static('public'));

app.get('/api/health', (req, res) => {
  res.json({ healthy: true });
});

export default app;

import app from './app.js';

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

